// Decision trees: one Mermaid `.mmd` per Listing, generated by code from the stored Listing
// (its Screen Checks) and its Application (the Event log), never from the LLM. Regenerated
// in full whenever either changes; deleted with the Listing. File:
// <data>/decision-trees/<encodeURIComponent(listing id)>.mmd. See core-conventions.md.
import { mkdir } from "node:fs/promises";
import { join } from "node:path";
import { type EventLogEntry, statusLabel } from "./application.ts";
import type { Check } from "./screen-check.ts";
import { type StoredRecord, writeThenReplace } from "./store.ts";

export const TREE_DIR = "decision-trees";

/** The tree's path relative to the data directory, as stored on the Listing. */
export function treePath(listingId: string): string {
  return `${TREE_DIR}/${encodeURIComponent(listingId)}.mmd`;
}

/** The colour key shared with the terminal and the pipeline view (#43). */
const CLASS_DEFS = [
  "classDef src    fill:#eef1f6,stroke:#5b6b85,color:#1d2433",
  "classDef ok     fill:#dff3e7,stroke:#1f7a4d,stroke-width:2px,color:#123d27",
  "classDef warn   fill:#fff1cc,stroke:#b07d00,stroke-width:2px,color:#4a3500",
  "classDef bad    fill:#fbe0dc,stroke:#a33a2b,stroke-width:3px,color:#5a1a12",
  "classDef nr     fill:#f2f2f2,stroke:#b5b5b5,stroke-dasharray:4 3,color:#8a8a8a",
  "classDef human  fill:#dce7ff,stroke:#2b59c3,stroke-width:2px,color:#132a63",
  "classDef out    fill:#ece0fb,stroke:#6b3fb0,stroke-width:2px,color:#2e1656",
  "classDef outbad fill:#a33a2b,stroke:#5a1a12,color:#fff",
];

const MAX_TEXT = 140;

/** Text safe inside a quoted Mermaid label: entity codes for quotes and angle brackets. */
function esc(text: string): string {
  const flat = text.replace(/\s+/g, " ").trim();
  const short = flat.length > MAX_TEXT ? `${flat.slice(0, MAX_TEXT - 1)}…` : flat;
  return short.replace(/"/g, "#quot;").replace(/</g, "#lt;").replace(/>/g, "#gt;");
}

/** Node class from a Check: red only when it excludes; a failure that doesn't is amber. */
function checkClass(c: Check): string {
  if (c.status === "not_reached") return "nr";
  if (c.status === "pass") return "ok";
  if (c.status === "fail" && c.effect === "exclude") return "bad";
  return "warn";
}

export function nodeId(check: string): string {
  return `c_${check.replace(/[^A-Za-z0-9]/g, "_")}`;
}

interface Screen {
  outcome: "shortlist" | "excluded";
  excluded_by: string | null;
  checks: Check[];
  fit?: { score: number; band: string };
}

/** The `.mmd` text for one Listing, from its stored records only. */
export function renderTree(listing: StoredRecord, application?: StoredRecord): string {
  const screen = listing.screen as Screen;
  const out: string[] = [
    `%% Job Butler Decision tree for Listing ${listing.id}.`,
    "%% Generated from stored records; regenerated in full on every change. Don't edit.",
    "flowchart TD",
  ];
  const location = listing.location ? `<br/>${esc(String(listing.location))}` : "";
  out.push(
    `  L["<b>${esc(String(listing.company))}</b><br/>${esc(String(listing.title))}${location}"]:::src`,
  );
  overrideNodes(listing).forEach((node, i) => {
    out.push(`  o${i + 1}${node}:::human`, `  L -.- o${i + 1}`);
  });

  let prev = "L";
  let dashed = false;
  for (const c of screen.checks) {
    const id = nodeId(c.check);
    out.push(
      `  ${id}["<b>${esc(c.name)}</b><br/><small>${esc(c.rule)}</small><br/>→ ${esc(c.result)}` +
        `<br/><i>${esc(c.citation)}</i>"]:::${checkClass(c)}`,
    );
    out.push(`  ${prev} ${dashed ? "-.->" : "-->"} ${id}`);
    if (c.check === screen.excluded_by) {
      out.push(`  ${id} -->|excluded| X(["Excluded · restorable"]):::outbad`);
      dashed = true;
    }
    if (c.status === "not_reached") dashed = true;
    prev = id;
  }

  if (screen.outcome === "excluded") return finish(out);
  const fit = screen.fit ? ` · Fit ${screen.fit.score} ${screen.fit.band}` : "";
  if (application === undefined) {
    const end = listing.gone
      ? `GONE(["Gone from its board · off the Shortlist${fit}"]):::out`
      : `SL(["On the Shortlist${fit}"]):::out`;
    out.push(`  ${prev} --> ${end}`);
    return finish(out);
  }

  // After the pick: a chain over the Application's Event log.
  out.push(`  ${prev} --> SL(["Shortlisted${fit}"]):::ok`);
  prev = "SL";
  const events = (application.event_log as EventLogEntry[] | undefined) ?? [];
  events.forEach((e, i) => {
    const id = `e${i + 1}`;
    const move = `${e.from ? `${statusLabel(e.from)} → ` : ""}${statusLabel(e.to)}`;
    const cite = e.approval
      ? `Your Approval (${e.approval.checkpoint}, ${e.approval.approved_at}): ${e.approval.action}`
      : `${e.stage} · ${e.at}`;
    out.push(
      `  ${id}["<b>${esc(move)}</b><br/><small>${esc(e.stage)} · ${esc(e.at)}</small><br/>` +
        `${esc(e.reason)}<br/><i>${esc(cite)}</i>"]:::${e.approval ? "human" : "ok"}`,
    );
    out.push(`  ${prev} --> ${id}`);
    prev = id;
  });
  out.push(`  ${prev} --> ST(["Status: ${esc(statusLabel(String(application.status)))}"]):::out`);
  return finish(out);
}

interface Override {
  kind: string;
  at?: string;
  alias?: string;
  from?: string;
  into?: string;
  check?: string;
}

/**
 * One node label per override on the Listing (`listing.overrides`, the job seeker's own
 * decisions). Split (#37): `into` on the Listing split from, `from` on the one split off.
 * #39 (restore) and #42 (limit override) add their kinds here.
 */
function overrideNodes(listing: StoredRecord): string[] {
  const overrides = Array.isArray(listing.overrides) ? (listing.overrides as Override[]) : [];
  return overrides.map((o) => {
    let what = `${o.kind}`;
    if (o.kind === "restore")
      what = `Restored from exclusion by ${o.check ?? "a check"}: back at its fit position, still flagged`;
    if (o.kind === "split" && o.into)
      what = `Split off ${o.into}: a different job, never merged again`;
    else if (o.kind === "split" && o.from) {
      what = `Split from ${o.from}: a different job, never merged again`;
    }
    return (
      `["<b>Override: ${esc(o.kind)}</b><br/>${esc(what)}<br/>` +
      `<i>Your decision${o.at ? ` · ${esc(o.at)}` : ""}</i>"]`
    );
  });
}

function finish(lines: string[]): string {
  return `${[...lines, ...CLASS_DEFS.map((d) => `  ${d}`)].join("\n")}\n`;
}

/**
 * Write the trees for these Listings (each with its Application, if any). Call inside the
 * same `withWriter` as the change that made them stale. A Listing Screen hasn't decided on
 * has no tree.
 */
export async function writeTrees(
  dataDir: string,
  listings: StoredRecord[],
  applications: StoredRecord[],
): Promise<void> {
  const byListing = new Map(applications.map((a) => [a.listing, a]));
  await mkdir(join(dataDir, TREE_DIR), { recursive: true, mode: 0o700 });
  for (const listing of listings) {
    if (listing.screen === undefined || listing.screen === null) continue;
    const text = renderTree(listing, byListing.get(listing.id));
    await writeThenReplace(join(dataDir, treePath(listing.id)), text);
  }
}
